@@ -3,24 +3,28 @@ use crate::{from_env, parse_file, FileError, Value};
 /// Merges `top` over `base`: tables merge key by key, at every depth; anything else in `top`
 /// replaces what `base` has.
 pub fn merge(base: Value, top: Value) -> Value {
-    merge_at(base, top, 0)
+    merge_at(base, top)
 }

-fn merge_at(base: Value, top: Value, depth: usize) -> Value {
+fn merge_at(base: Value, top: Value) -> Value {
     match (base, top) {
         (Value::Table(mut b), Value::Table(t)) => {
             for (k, tv) in t {
-                let merged = match b.remove(&k) {
-                    // Sections merge recursively; inside a section, keep what is already set
-                    // unless the new layer adds it.
-                    Some(bv) if depth == 0 => merge_at(bv, tv, depth + 1),
-                    Some(bv) => merge_at(tv, bv, depth + 1),
-                    None => tv,
-                };
-                b.insert(k, merged);
+                match b.remove(&k) {
+                    // When both sides are tables, merge recursively.
+                    Some(bv) => {
+                        let merged = merge_at(bv, tv);
+                        b.insert(k, merged);
+                    }
+                    // Otherwise `top` wins for this key.
+                    None => {
+                        b.insert(k, tv);
+                    }
+                }
             }
             Value::Table(b)
         }
+        // For non-tables, `top` replaces `base`.
         (_, top) => top,
     }
 }
